import { useState, useRef } from "react";
import gameService from '../../services/gameService';
import './GameConstructor.css';

function GameConstructor() {
  const [gameType, setGameType] = useState('wheel');
  const [gameContent, setGameContent] = useState(null);
  const [gameName, setGameName] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [saveMessage, setSaveMessage] = useState('');
  const [wheelItems, setWheelItems] = useState([
    { wordId: 1, wordLabel: "Крутить", color: "#E0BBE4", textPosition: { x: 0, y: 0 } },
    { wordId: 2, wordLabel: "Удача", color: "#FEC8D8", textPosition: { x: 0, y: 0 } },
    { wordId: 3, wordLabel: "Приз", color: "#FFDFD3", textPosition: { x: 0, y: 0 } },
    { wordId: 4, wordLabel: "Риск", color: "#B6EEBD", textPosition: { x: 0, y: 0 } },
  ]);

  const handleGameNaming = (event) => {
    setGameName(event.target.value);
  };

  const handleSaveGame = async () => {
    if (!gameName.trim()) {
      setSaveMessage('Пожалуйста, введите название игры');
      return;
    }

    if (gameType === 'wheel' && wheelItems.length === 0) {
      setSaveMessage('Добавьте хотя бы один элемент в колесо');
      return;
    }

    setIsSaving(true);
    setSaveMessage('');

    try {
      await gameService.saveWheelGame(gameName, wheelItems);
      setSaveMessage('Игра успешно сохранена!');
    } catch (error) {
      console.error('Ошибка при сохранении игры:', error);
      setSaveMessage('Ошибка при сохранении игры');
    } finally {
      setIsSaving(false);
    }
  };

  function ConstructorEngine({ gameName, gameType, wheelItems, setWheelItems }) {
    if (gameType === 'wheel') {
      return (
        <WheelGame 
          gameName={gameName} 
          items={wheelItems}
          onItemsChange={setWheelItems}
        />
      );
    } else if (gameType === 'match') {
      return (
        <div className="game-type-placeholder">
          <h3>Игра на совпадение: {gameName || 'Без названия'}</h3>
          <p>Функционал игры на совпадение скоро появится!</p>
        </div>
      );
    } else if (gameType === 'quiz') {
      return (
        <div className="game-type-placeholder">
          <h3>Игра-викторина: {gameName || 'Без названия'}</h3>
          <p>Функционал викторины скоро появится!</p>
        </div>
      );
    }
    return null;
  }
        
  return (
    <div className="game-constructor-container card">
      <h1>Конструктор игр</h1>
      
      <div className="form-group">
        <label htmlFor="gameName">Название игры</label>
        <input
          type="text"
          id="gameName"
          value={gameName}
          onChange={handleGameNaming}
          placeholder="Например: 'Колесо удачи'"
        />
      </div>
      
      <div className="button-group game-type-selector">
        <button
          type="button"
          onClick={() => setGameType('wheel')}
          className={`btn ${gameType === 'wheel' ? 'btn-primary' : 'btn-outline'}`}
        >
          Колесо
        </button>
        <button
          type="button"
          onClick={() => setGameType('match')}
          className={`btn ${gameType === 'match' ? 'btn-primary' : 'btn-outline'}`}
        >
          Совпадения
        </button>
        <button
          type="button"
          onClick={() => setGameType('quiz')}
          className={`btn ${gameType === 'quiz' ? 'btn-primary' : 'btn-outline'}`}
        >
          Викторина
        </button>
        <button
          type="button"
          onClick={handleSaveGame}
          disabled={isSaving || !gameName.trim()}
          className={`btn ${isSaving ? 'btn-outline' : 'btn-success'}`}
        >
          {isSaving ? 'Сохранение...' : 'Сохранить игру'}
        </button>
      </div>
      
      {saveMessage && (
        <div className={`alert ${saveMessage.includes('успешно') ? 'alert-success' : 'alert-error'}`}>
          {saveMessage}
        </div>
      )}
      
      {ConstructorEngine({ gameName, gameType, wheelItems, setWheelItems })}
    </div>
  );
}

//-----------------------------------------------------
// Wheel Game Component
//-----------------------------------------------------
const WheelGame = ({ gameName, items, onItemsChange }) => {
  const textPos = { x: 0, y: 0 };
  const [inputValue, setInputValue] = useState("");
  const [rotationDeg, setRotationDeg] = useState(0);
  const [resultLabel, setResultLabel] = useState("");
  const spinningRef = useRef(false);
  const [isSpinning, setIsSpinning] = useState(false);
  const [keepTextUpright, setKeepTextUpright] = useState(true);

  const palette = [
    "#B3E5FC", // Light Blue
    "#81D4FA", // Cerulean
    "#4FC3F7", // Sky Blue
    "#29B6F6", // Deep Sky Blue
    "#03A9F4", // Blue
    "#039BE5", // Dark Blue
    "#0288D1", // Midnight Blue
    "#0277BD", // Prussian Blue
    "#01579B", // Navy Blue
    "#002171"  // Darker Navy
  ];

  const handleInputChange = (event) => {
    setInputValue(event.target.value);
  };

  const handleSubmit = () => {
    const label = inputValue.trim();
    if (!label) return;
    const nextId = items.length
      ? Math.max(...items.map((i) => i.wordId)) + 1
      : 1;
    const color = palette[nextId % palette.length];
    const newItem = {
      wordId: nextId,
      wordLabel: label,
      color,
      textPosition: textPos,
    };
    onItemsChange((prev) => [...prev, newItem]);
    setInputValue("");
  };

  const handleDelete = () => {
    const label = inputValue.trim();
    if (!label) return;
    onItemsChange((prevItems) =>
      prevItems.filter((item) => item.wordLabel !== label)
    );
    setInputValue("");
  };

  const getPointerIndex = (deg, count) => {
    if (count <= 0) return -1;
    const adjusted = (((270 - deg) % 360) + 360) % 360;
    const step = 360 / count;
    const index = Math.floor(adjusted / step);
    return Math.min(Math.max(index, 0), count - 1);
  };

  const spin = () => {
    if (spinningRef.current || isSpinning || items.length === 0) return;
    spinningRef.current = true;
    setIsSpinning(true);
    setResultLabel("");

    const count = items.length;
    const current = rotationDeg;
    const targetIndex = Math.floor(Math.random() * count);
    const step = 360 / count;
    const targetCenterDeg = targetIndex * step + step / 2;
    const baseTargetRotation = 270 - targetCenterDeg;
    const extraTurns = 3;
    const targetRotation = baseTargetRotation + 360 * extraTurns;

    const durationMs = 5000;
    const startTs = performance.now();
    const startRotation = current;
    const deltaToBase =
      (((baseTargetRotation - startRotation) % 360) + 360) % 360;
    const endRotation = startRotation + 360 * extraTurns + deltaToBase;

    const easeOutCubic = (t) => 1 - Math.pow(1 - t, 3);

    const tick = (now) => {
      const elapsed = now - startTs;
      const t = Math.min(elapsed / durationMs, 1);
      const eased = easeOutCubic(t);
      const value = startRotation + (endRotation - startRotation) * eased;
      setRotationDeg(value);
      if (t < 1) {
        requestAnimationFrame(tick);
      } else {
        const finalIndex = getPointerIndex(value, count);
        const label = finalIndex >= 0 ? items[finalIndex]?.wordLabel ?? "" : "";
        setResultLabel(label);
        spinningRef.current = false;
        setIsSpinning(false);
      }
    };

    requestAnimationFrame(tick);
  };

  const WordWheel = ({ items, size, thickness, rotationDeg, keepTextUpright }) => {
    const computeAnglesEqual = (count) => {
      if (count <= 0) return [];
      const step = 360 / count;
      const spans = [];
      for (let i = 0; i < count; i++) {
        const startDeg = i * step;
        const endDeg = (i + 1) * step;
        spans.push({ startDeg, endDeg });
      }
      spans[spans.length - 1].endDeg = 360;
      return spans;
    };

    const donutSlicePath = (cx, cy, rOuter, rInner, startDeg, endDeg) => {
      const toRad = (d) => (d * Math.PI) / 180;
      const pt = (r, a) => ({
        x: cx + r * Math.cos(toRad(a)),
        y: cy + r * Math.sin(toRad(a)),
      });
      const largeArc = (endDeg - startDeg + 360) % 360 > 180 ? 1 : 0;
      const p1 = pt(rOuter, startDeg), p2 = pt(rOuter, endDeg);
      const p3 = pt(rInner, endDeg), p4 = pt(rInner, startDeg);
      return `M ${p1.x} ${p1.y} A ${rOuter} ${rOuter} 0 ${largeArc} 1 ${p2.x} ${p2.y} L ${p3.x} ${p3.y} A ${rInner} ${rInner} 0 ${largeArc} 0 ${p4.x} ${p4.y} Z`;
    };

    const wheelDraw = () => {
      const spans = computeAnglesEqual(items.length);
      const cx = size / 2;
      const cy = size / 2;
      const rOuter = Math.min(cx, cy) - 5;
      const rInner = Math.max(0, rOuter - thickness);
      const toRad = (d) => (d * Math.PI) / 180;
      const polarToCartesian = (r, angleDeg) => ({
        x: cx + r * Math.cos(toRad(angleDeg)),
        y: cy + r * Math.sin(toRad(angleDeg)),
      });

      return (
        <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`}>
          <g transform={`rotate(${rotationDeg} ${cx} ${cy})`}>
            {spans.map((span, i) => {
              const d = donutSlicePath(
                cx,
                cy,
                rOuter,
                rInner,
                span.startDeg,
                span.endDeg
              );
              const midAngle = (span.startDeg + span.endDeg) / 2;
              const textRadius = (rOuter + rInner) / 2;
              const { x, y } = polarToCartesian(textRadius, midAngle);
              return (
                <g key={i}>
                  <path d={d} fill={items[i].color ?? "#ccc"} />
                  <text
                    x={x}
                    y={y}
                    fill="#222"
                    fontSize={Math.max(10, thickness * 0.3)}
                    textAnchor="middle"
                    dominantBaseline="middle"
                    transform={
                      keepTextUpright
                        ? `rotate(${-rotationDeg} ${x} ${y})`
                        : undefined
                    }
                  >
                    {items[i].wordLabel}
                  </text>
                </g>
              );
            })}
          </g>
          <polygon points={`${cx - 6},10 ${cx + 6},10 ${cx},28`} fill="#333" />
        </svg>
      );
    };

    return wheelDraw();
  };

  return (
    <div className="wheel-game-designer card">
      <h2 className="game-constructor-subtitle">Настройте ваше колесо</h2>
      
      <div className="game-designer-controls">
        <div className="form-group input-group">
          <input
            type="text"
            value={inputValue}
            onChange={handleInputChange}
            placeholder="Введите вариант"
          />
          <button 
            onClick={handleSubmit}
            className="btn btn-primary"
          >
            Добавить
          </button>
        </div>
        
        <div className="button-group">
          <button 
            onClick={handleDelete}
            className="btn btn-outline-danger"
          >
            Удалить
          </button>
          <button
            onClick={spin}
            disabled={isSpinning || items.length === 0}
            className={`btn ${isSpinning || items.length === 0 ? 'btn-outline' : 'btn-primary'}`}
          >
            {isSpinning ? 'Крутим...' : 'Крутить колесо'}
          </button>
        </div>
        
        <div className="form-group checkbox-group">
          <input
            type="checkbox"
            id="keepTextUpright"
            checked={keepTextUpright}
            onChange={(e) => setKeepTextUpright(e.target.checked)}
          />
          <label htmlFor="keepTextUpright">Вертикальный текст</label>
        </div>
      </div>
      
      <div className="wheel-display">
        <WordWheel
          items={items}
          size={400}
          thickness={120}
          rotationDeg={rotationDeg}
          keepTextUpright={keepTextUpright}
        />
      </div>
      
      {resultLabel && (
        <div className="alert alert-success mt-3">
          <strong>Победитель:</strong> {resultLabel}
        </div>
      )}
    </div>
  );
};

export default GameConstructor;
